CREATE TABLE IF NOT EXISTS migrations(version INTEGER PRIMARY KEY);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS registrations(id INTEGER PRIMARY KEY,user INTEGER NOT NULL,name TEXT NOT NULL,document TEXT NOT NULL,mail TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',decider INTEGER,decided TEXT,reason TEXT,created TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS active_user ON registrations(user) WHERE status IN ('pending','approved');
CREATE UNIQUE INDEX IF NOT EXISTS active_document ON registrations(document) WHERE status IN ('pending','approved');
CREATE TABLE IF NOT EXISTS tables(id INTEGER PRIMARY KEY,message TEXT UNIQUE,author INTEGER NOT NULL,attachment TEXT,published TEXT NOT NULL,period TEXT NOT NULL,raw TEXT,state TEXT NOT NULL,prices TEXT NOT NULL DEFAULT '{}',error TEXT);
CREATE TABLE IF NOT EXISTS withdrawals(id INTEGER PRIMARY KEY,user INTEGER NOT NULL,product TEXT NOT NULL,seeds INTEGER NOT NULL CHECK(seeds>0),yield INTEGER NOT NULL CHECK(yield>0),rate TEXT NOT NULL,created TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'open',operation TEXT UNIQUE);
CREATE TABLE IF NOT EXISTS quotes(id INTEGER PRIMARY KEY,withdrawal INTEGER NOT NULL REFERENCES withdrawals(id),table_id INTEGER NOT NULL REFERENCES tables(id),price INTEGER NOT NULL,total INTEGER NOT NULL,farm INTEGER NOT NULL,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sales(id INTEGER PRIMARY KEY,withdrawal INTEGER UNIQUE NOT NULL REFERENCES withdrawals(id),table_id INTEGER NOT NULL REFERENCES tables(id),price INTEGER NOT NULL,total INTEGER NOT NULL,farm INTEGER NOT NULL,employee INTEGER NOT NULL,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS payments(id INTEGER PRIMARY KEY,sale INTEGER UNIQUE NOT NULL REFERENCES sales(id),user INTEGER NOT NULL,amount INTEGER NOT NULL,state TEXT NOT NULL DEFAULT 'pending',receiver INTEGER,confirmed_by INTEGER,confirmed_at TEXT,reported_at TEXT);
CREATE TABLE IF NOT EXISTS ledger(id INTEGER PRIMARY KEY,payment INTEGER UNIQUE REFERENCES payments(id),amount INTEGER NOT NULL,actor INTEGER NOT NULL,receiver INTEGER,created TEXT NOT NULL,reason TEXT NOT NULL,reverses INTEGER UNIQUE REFERENCES ledger(id));
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY,actor INTEGER NOT NULL,event TEXT NOT NULL,payload TEXT NOT NULL,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS panels(kind TEXT PRIMARY KEY,channel INTEGER NOT NULL,message INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS notices(period TEXT PRIMARY KEY,state TEXT NOT NULL DEFAULT 'pending',message INTEGER);
